```js
// Resolves ball/brick collisions: bounces the ball off the face it hit,
// pushes it out of the brick, breaks the brick and scores. Pure logic.
// Returns the number of bricks broken.
export function bounceBricks(state) {
  const { ball, bricks } = state;
  let broken = 0;
  let flippedX = false;
  let flippedY = false;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;

    // Penetration depth on each axis: the smaller one is the face hit.
    const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

    if (overlapX < overlapY) {
      // Side hit: flip vx once per pass, push out horizontally.
      if (!flippedX) {
        ball.vx = ball.x < brick.x + brick.w / 2 ? -Math.abs(ball.vx) : Math.abs(ball.vx);
        flippedX = true;
      }
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    } else if (overlapY < overlapX) {
      // Top/bottom hit: flip vy once per pass, push out vertically.
      if (!flippedY) {
        ball.vy = ball.y < brick.y + brick.h / 2 ? -Math.abs(ball.vy) : Math.abs(ball.vy);
        flippedY = true;
      }
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    } else {
      // Corner: equal penetration on both axes, flip both (once per axis).
      if (!flippedX) {
        ball.vx = -ball.vx;
        flippedX = true;
      }
      if (!flippedY) {
        ball.vy = -ball.vy;
        flippedY = true;
      }
      if (ball.x < brick.x + brick.w / 2) ball.x = brick.x - ball.r;
      else ball.x = brick.x + brick.w + ball.r;
      if (ball.y < brick.y + brick.h / 2) ball.y = brick.y - ball.r;
      else ball.y = brick.y + brick.h + ball.r;
    }

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    broken += 1;
  }
  return broken;
}
```

