```js
export function step(state, dt) {
  const { ball, paddle } = state;

  // Sub-step the movement: a single jump can never be longer than the
  // thinnest obstacle (a brick plus the ball's own diameter), so the ball
  // cannot skip over a brick or the paddle between two collision checks
  // (tunneling). Bricks are resolved after every sub-step.
  const speed = Math.hypot(ball.vx, ball.vy);
  const distance = speed * dt;
  const steps = Math.max(1, Math.ceil(distance / MAX_STEP));
  const subDt = dt / steps;

  for (let i = 0; i < steps; i++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks: bounce + break + score (moved out of the render loop).
    bounceBricks(state);

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}
```

