// Builds a minimal state: one brick, a custom ball. Keeps the tests focused
// on the collision response instead of the whole grid.
function stateWithBrick(ball, brick) {
  const state = createState(1);
  state.ball = ball;
  state.bricks = [brick];
  return state;
}

// --- Defect #1: bricks never bounced the ball back -------------------------
// (face vs coin: the hit face is the axis of least penetration; equal
//  penetration = corner, both components flip. collant: the ball is pushed
//  back out of the brick so it cannot re-collide on the next pass.)

test('bounceBricks: descending ball bounces off the top face and is pushed out', () => {
  const state = stateWithBrick(
    { x: 136, y: 96, r: 7, vx: 0, vy: 300 }, // coming DOWN onto the brick
    { x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 10 },
  );
  bounceBricks(state);
  assert.equal(state.ball.vy, -300, 'vy flips from DOWN to UP');
  assert.equal(state.ball.y, 100 - 7, 'ball is pushed above the brick');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball no longer overlaps');
  assert.equal(state.bricks[0].alive, false, 'brick is broken');
});

test('bounceBricks: ascending ball bounces off the bottom face and is pushed out', () => {
  const state = stateWithBrick(
    { x: 136, y: 124, r: 7, vx: 0, vy: -300 }, // coming UP into the brick
    { x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 10 },
  );
  bounceBricks(state);
  assert.equal(state.ball.vy, 300, 'vy flips from UP to DOWN');
  assert.equal(state.ball.y, 120 + 7, 'ball is pushed below the brick');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball no longer overlaps');
});

test('bounceBricks: ball entering from the right bounces off the side face', () => {
  const state = stateWithBrick(
    { x: 178, y: 110, r: 7, vx: -300, vy: 0 }, // moving LEFT into the right face
    { x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 10 },
  );
  bounceBricks(state);
  assert.equal(state.ball.vx, 300, 'vx flips from LEFT to RIGHT');
  assert.equal(state.ball.x, 172 + 7, 'ball is pushed out on the right');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball no longer overlaps');
});

test('bounceBricks: ball entering from the left bounces off the side face', () => {
  const state = stateWithBrick(
    { x: 94, y: 110, r: 7, vx: 300, vy: 0 }, // moving RIGHT into the left face
    { x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 10 },
  );
  bounceBricks(state);
  assert.equal(state.ball.vx, -300, 'vx flips from RIGHT to LEFT');
  assert.equal(state.ball.x, 100 - 7, 'ball is pushed out on the left');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball no longer overlaps');
});

test('bounceBricks: corner hit with equal penetration flips both axes', () => {
  const state = stateWithBrick(
    { x: 100, y: 100, r: 7, vx: -300, vy: 300 }, // exactly on the top-left corner
    { x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 10 },
  );
  bounceBricks(state);
  assert.equal(state.ball.vx, 300, 'vx flips');
  assert.equal(state.ball.vy, -300, 'vy flips');
  assert.equal(state.ball.x, 100 - 7, 'pushed out on the left');
  assert.equal(state.ball.y, 100 - 7, 'pushed out on top');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'ball no longer overlaps');
});

test('bounceBricks: a brick is counted and broken only once', () => {
  const state = stateWithBrick(
    { x: 136, y: 96, r: 7, vx: 0, vy: 300 },
    { x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 100 },
  );
  bounceBricks(state);
  const score = state.score;
  const combo = state.combo;
  bounceBricks(state); // same overlap, brick already dead
  assert.equal(state.score, score, 'no double score');
  assert.equal(state.combo, combo, 'no double combo');
});

