// --- Physics (movement + wall/paddle/brick bounces) -----------------------

// Longest sub-step of the ball (px). Kept at BALL_R so that no single jump
// can be longer than the thinnest obstacle (a brick + the ball diameter =
// 34 px), nor cross a brick's midline in one go (half-height = 10 px, which
// would make the penetration-based face detection pick the wrong face), nor
// jump over a brick seam (gap = 8 px). Movement is therefore swept as several
// sub-steps, and brick collisions are resolved after every sub-step.
const MAX_SUB_STEP = BALL_R;

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks (via bounceBricks). The movement is
// sub-stepped so the ball can never skip over a brick or the paddle between
// two collision checks, whatever the speed (tunneling).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const speed = Math.hypot(ball.vx, ball.vy);
  const subSteps = Math.max(1, Math.ceil((speed * dt) / MAX_SUB_STEP));
  const subDt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: bounce + break + score (pure logic, see bounceBricks).
    bounceBricks(state);

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

